//! Strict stock evaluator distribution decoding and relocatable rootfs materialization.
//!
//! The embedded manifest is generated by
//! `tools/generate_stock_evaluator_manifest.py:1-1013`. The runner repeats its
//! complete source-closure verification before advertising a distribution and
//! again while copying one fresh, single-link, read-only worker root. Python
//! never selects an executable, host path, argument, environment variable, or
//! isolation implementation.

use std::any::Any;
use std::collections::{BTreeMap, BTreeSet};
use std::ffi::OsString;
use std::fmt;
use std::fs::{File, OpenOptions};
use std::io::{Read, Write};
use std::path::{Component, Path, PathBuf};
use std::sync::Arc;

use aiperf_accuracy as accuracy;
use anyhow::{Context, Result, anyhow, bail, ensure};
use async_trait::async_trait;
use base64::Engine as _;
use base64::engine::general_purpose::{STANDARD as BASE64_STANDARD, URL_SAFE_NO_PAD};
use serde::Deserialize;
use uuid::Uuid;

const STOCK_MANIFEST_BYTES: &[u8] =
    include_bytes!("../../../src/aiperf/accuracy/evaluation/manifests/stock_distributions.json");
const STOCK_MANIFEST_SCHEMA: &str = "aiperf-stock-evaluator-distributions-v1";
const ISOLATION_PROFILE: &str = "linux-bubblewrap-rootfs-process-tree-v2";
const PLATFORM: &str = "linux-x86_64";
const PYTHON_IMPLEMENTATION: &str = "cpython";
const PYTHON_VERSION: &str = "3.12.10";
const PYTHON_ABI: &str = "cpython-312-x86_64-linux-gnu";
const PROGRAM: &str = "runtime/bin/python3.12";
const CURRENT_DIR: &str = "work";
const SITE_PACKAGES_RELATIVE: &str = "lib/python3.12/site-packages";
const ROOTFS_MOUNTPOINTS: &[&str] = &["work", "staging", "proc", "dev", "run/aiperf"];

/// Replaceable resolver for deployment-owned runtime and package sources.
///
/// A packaged runner can inject another resolver without changing manifest
/// validation or materialization. The stock implementation discovers only the
/// Python environment already containing the runner; no authored path crosses
/// this seam.
trait StockClosureSourceResolver: fmt::Debug + Send + Sync {
    fn python_runtime_root(&self, resolver: &PythonRuntimeResolver) -> Result<PathBuf>;
    fn system_root(&self, resolver: &SystemRootResolver) -> Result<PathBuf>;
    fn site_package_roots(&self) -> Result<Vec<PathBuf>>;
}

#[derive(Clone, Copy, Debug, Default)]
struct EnvironmentStockClosureSourceResolver;

impl StockClosureSourceResolver for EnvironmentStockClosureSourceResolver {
    fn python_runtime_root(&self, resolver: &PythonRuntimeResolver) -> Result<PathBuf> {
        validate_python_identity(
            &resolver.implementation,
            &resolver.version,
            &resolver.abi,
            &resolver.platform,
        )?;
        let relative = strict_relative_path(
            &resolver.executable_relative_path,
            "python executable_relative_path",
        )?;
        let mut roots = Vec::new();
        for executable in python_executable_candidates() {
            if let Ok(canonical) = executable.canonicalize()
                && let Some(root) = canonical.parent().and_then(Path::parent)
            {
                roots.push(root.to_path_buf());
            }
        }
        roots.sort();
        roots.dedup();
        let mut matches = Vec::new();
        for root in roots {
            let executable = root.join(&relative);
            if verify_regular_file_digest(&executable, &resolver.executable_sha256).is_ok() {
                matches.push(root);
            }
        }
        ensure!(
            matches.len() == 1,
            "pinned evaluator CPython runtime resolved to {} roots",
            matches.len()
        );
        Ok(matches.remove(0))
    }

    fn system_root(&self, resolver: &SystemRootResolver) -> Result<PathBuf> {
        ensure!(
            cfg!(all(target_os = "linux", target_arch = "x86_64")) && resolver.platform == PLATFORM,
            "stock evaluator system closure requires {PLATFORM}"
        );
        Ok(PathBuf::from("/"))
    }

    fn site_package_roots(&self) -> Result<Vec<PathBuf>> {
        let mut roots = Vec::new();
        for environment in python_environment_roots() {
            let candidate = environment.join(SITE_PACKAGES_RELATIVE);
            if candidate.is_dir() {
                roots.push(candidate.canonicalize().with_context(|| {
                    format!(
                        "canonicalizing evaluator site-packages {}",
                        candidate.display()
                    )
                })?);
            }
        }
        roots.sort();
        roots.dedup();
        ensure!(
            !roots.is_empty(),
            "no deployment-owned Python 3.12 site-packages root was found"
        );
        Ok(roots)
    }
}

fn python_executable_candidates() -> Vec<PathBuf> {
    let mut candidates = Vec::new();
    for environment in python_environment_roots() {
        candidates.push(environment.join("bin/python3.12"));
        candidates.push(environment.join("bin/python"));
    }
    if let Some(path) = std::env::var_os("PATH") {
        for directory in std::env::split_paths(&path) {
            candidates.push(directory.join("python3.12"));
            candidates.push(directory.join("python"));
        }
    }
    candidates
}

fn python_environment_roots() -> Vec<PathBuf> {
    let mut roots = ["VIRTUAL_ENV", "CONDA_PREFIX"]
        .into_iter()
        .filter_map(std::env::var_os)
        .map(PathBuf::from)
        .collect::<Vec<_>>();
    if roots.is_empty()
        && let Some(path) = std::env::var_os("PATH")
    {
        for directory in std::env::split_paths(&path) {
            if directory.file_name().is_some_and(|name| name == "bin")
                && let Some(parent) = directory.parent()
            {
                roots.push(parent.to_path_buf());
            }
        }
    }
    roots.sort();
    roots.dedup();
    roots
}

#[derive(Debug, Deserialize)]
#[serde(deny_unknown_fields)]
struct StockDistributionManifest {
    schema_version: String,
    shared_closures: BTreeMap<String, SharedClosure>,
    distributions: Vec<StockDistribution>,
}

impl StockDistributionManifest {
    fn embedded() -> Result<Self> {
        let manifest: Self = serde_json::from_slice(STOCK_MANIFEST_BYTES)
            .context("decoding embedded stock evaluator distribution manifest")?;
        manifest.validate()?;
        Ok(manifest)
    }

    fn validate(&self) -> Result<()> {
        ensure!(
            self.schema_version == STOCK_MANIFEST_SCHEMA,
            "unsupported stock evaluator manifest schema {:?}",
            self.schema_version
        );
        ensure!(
            !self.shared_closures.is_empty() && !self.distributions.is_empty(),
            "stock evaluator manifest cannot be empty"
        );
        let mut distributions = BTreeSet::new();
        for (id, closure) in &self.shared_closures {
            validate_open_manifest_id(id, "shared closure ID")?;
            closure.validate()?;
        }
        for distribution in &self.distributions {
            distribution.validate(self)?;
            ensure!(
                distributions.insert(distribution.distribution_id.clone()),
                "duplicate stock evaluator distribution {:?}",
                distribution.distribution_id
            );
        }
        Ok(())
    }

    fn distribution(&self, id: &accuracy::EvaluationDistributionId) -> Result<&StockDistribution> {
        self.distributions
            .iter()
            .find(|distribution| distribution.distribution_id == id.as_str())
            .ok_or_else(|| anyhow!("stock manifest has no distribution {id}"))
    }
}

#[derive(Debug, Deserialize)]
#[serde(deny_unknown_fields)]
struct SharedClosure {
    resolver: SharedClosureResolver,
    files: Vec<LogicalFile>,
}

impl SharedClosure {
    fn validate(&self) -> Result<()> {
        ensure!(!self.files.is_empty(), "shared closure has no files");
        self.resolver.validate()?;
        let mut destinations = BTreeSet::new();
        for file in &self.files {
            file.validate()?;
            ensure!(
                destinations.insert(file.destination.clone()),
                "shared closure contains duplicate destination {:?}",
                file.destination
            );
        }
        Ok(())
    }
}

#[derive(Debug, Deserialize)]
#[serde(tag = "kind", rename_all = "snake_case")]
enum SharedClosureResolver {
    PythonRuntimeRoot(PythonRuntimeResolver),
    SystemRoot(SystemRootResolver),
}

impl SharedClosureResolver {
    fn validate(&self) -> Result<()> {
        match self {
            Self::PythonRuntimeRoot(resolver) => resolver.validate(),
            Self::SystemRoot(resolver) => resolver.validate(),
        }
    }
}

