#[derive(Debug, Deserialize)]
#[serde(deny_unknown_fields)]
struct StockDistribution {
    provider_id: String,
    distribution_id: String,
    package: String,
    package_version: String,
    provider_source_sha256: String,
    worker_source_sha256: String,
    dependency_lock_sha256: String,
    oci_digest: Option<String>,
    config_schema_version: u32,
    config_schema_sha256: String,
    task_manifest: StockTaskManifest,
    operations: Vec<StockOperation>,
    isolation: StockIsolation,
    launch: StockLaunch,
    launch_closure_sha256: String,
}

impl StockDistribution {
    fn validate(&self, manifest: &StockDistributionManifest) -> Result<()> {
        accuracy::EvaluationProviderId::new(&self.provider_id)
            .map_err(|error| anyhow!(error.to_string()))?;
        accuracy::EvaluationDistributionId::new(&self.distribution_id)
            .map_err(|error| anyhow!(error.to_string()))?;
        ensure!(
            !self.package.trim().is_empty()
                && self.package.trim() == self.package
                && !self.package_version.trim().is_empty()
                && self.package_version.trim() == self.package_version,
            "stock evaluator package identity is invalid"
        );
        for (digest, label) in [
            (&self.provider_source_sha256, "provider source"),
            (&self.worker_source_sha256, "worker source"),
            (&self.dependency_lock_sha256, "dependency lock"),
            (&self.config_schema_sha256, "config schema"),
            (&self.launch_closure_sha256, "launch closure"),
        ] {
            validate_sha256(digest, label)?;
        }
        ensure!(
            self.oci_digest.is_none(),
            "stock relocatable distributions cannot claim an unused OCI digest"
        );
        ensure!(
            self.config_schema_version > 0,
            "stock evaluator config schema version must be positive"
        );
        self.task_manifest.validate()?;
        ensure!(
            !self.operations.is_empty(),
            "stock evaluator distribution has no operation"
        );
        let mut operation_ids = BTreeSet::new();
        for operation in &self.operations {
            operation.validate()?;
            ensure!(
                operation_ids.insert(operation.operation_id.clone()),
                "duplicate stock evaluator operation {:?}",
                operation.operation_id
            );
        }
        self.isolation.validate()?;
        self.launch.validate(manifest)?;
        Ok(())
    }

    fn descriptor(&self) -> Result<accuracy::EvaluationDistributionDescriptor> {
        Ok(accuracy::EvaluationDistributionDescriptor {
            distribution_id: accuracy::EvaluationDistributionId::new(&self.distribution_id)
                .map_err(|error| anyhow!(error.to_string()))?,
            package: self.package.clone(),
            package_version: self.package_version.clone(),
            provider_source_sha256: self.provider_source_sha256.clone(),
            worker_source_sha256: self.worker_source_sha256.clone(),
            dependency_lock_sha256: self.dependency_lock_sha256.clone(),
            oci_digest: self.oci_digest.clone(),
            launch_closure_sha256: self.launch_closure_sha256.clone(),
        })
    }
}

#[derive(Debug, Deserialize)]
#[serde(deny_unknown_fields)]
struct StockTaskManifest {
    resource: String,
    artifact_content_sha256: String,
    executable_tasks: Vec<String>,
}

impl StockTaskManifest {
    fn validate(&self) -> Result<()> {
        ensure!(
            self.resource
                .starts_with("aiperf.accuracy.evaluation.manifests/")
                && !self.executable_tasks.is_empty()
                && self
                    .executable_tasks
                    .iter()
                    .all(|task| !task.trim().is_empty() && task.trim() == task),
            "stock task manifest identity is invalid"
        );
        validate_sha256(&self.artifact_content_sha256, "stock task manifest SHA-256")
    }
}

#[derive(Debug, Deserialize)]
#[serde(deny_unknown_fields)]
struct StockOperation {
    operation_id: String,
    request_schema_sha256: String,
    response_schema_sha256: String,
    stream_schema_sha256: Option<String>,
    endpoint_capability: String,
}

impl StockOperation {
    fn validate(&self) -> Result<()> {
        let expected = accuracy::STOCK_EVALUATION_OPERATION_SCHEMAS
            .iter()
            .find(|schema| schema.operation_id == self.operation_id)
            .ok_or_else(|| anyhow!("unknown stock operation {:?}", self.operation_id))?;
        ensure!(
            self.request_schema_sha256 == expected.request_schema_sha256
                && self.response_schema_sha256 == expected.response_schema_sha256
                && self.stream_schema_sha256.as_deref()
                    == expected
                        .true_streaming
                        .then_some(expected.canonical_stream_schema_sha256)
                && self.endpoint_capability == expected.endpoint_capability,
            "stock operation {:?} schema/capability drifted",
            self.operation_id
        );
        Ok(())
    }
}

#[derive(Debug, Deserialize)]
#[serde(deny_unknown_fields)]
struct StockIsolation {
    profile_id: String,
    bubblewrap: PathBuf,
    bubblewrap_sha256: String,
    resource_limits: accuracy::EvaluatorResourceLimits,
}

impl StockIsolation {
    fn validate(&self) -> Result<()> {
        ensure!(
            self.profile_id == ISOLATION_PROFILE && self.bubblewrap.is_absolute(),
            "stock evaluator isolation profile/path drifted"
        );
        validate_sha256(&self.bubblewrap_sha256, "Bubblewrap SHA-256")?;
        ensure!(
            self.resource_limits.address_space_bytes > 0
                && self.resource_limits.file_size_bytes > 0
                && self.resource_limits.open_files > 0
                && self.resource_limits.processes > 0
                && self.resource_limits.cpu_seconds > 0,
            "stock evaluator resource limits must be positive"
        );
        Ok(())
    }

    fn implementation(&self) -> Result<Arc<dyn accuracy::EvaluatorIsolation>> {
        Ok(Arc::new(accuracy::BubblewrapEvaluatorIsolation::new(
            &self.bubblewrap,
            self.bubblewrap_sha256.clone(),
            self.resource_limits,
        )?))
    }
}

#[derive(Debug, Deserialize)]
#[serde(deny_unknown_fields)]
struct StockLaunch {
    shared_closure_ids: Vec<String>,
    python_environment: PythonEnvironment,
    program: String,
    args: Vec<String>,
    environment: BTreeMap<String, String>,
    current_dir: String,
    record_closures: Vec<RecordClosure>,
    embedded_files: Vec<EmbeddedFile>,
    metadata_overlays: Vec<MetadataOverlay>,
}

impl StockLaunch {
    fn validate(&self, manifest: &StockDistributionManifest) -> Result<()> {
        ensure!(
            !self.shared_closure_ids.is_empty()
                && !self.record_closures.is_empty()
                && !self.embedded_files.is_empty(),
            "stock launch closure is incomplete"
        );
        let mut shared = BTreeSet::new();
        for id in &self.shared_closure_ids {
            ensure!(
                manifest.shared_closures.contains_key(id) && shared.insert(id.clone()),
                "stock launch references unknown or duplicate shared closure {id:?}"
            );
        }
        self.python_environment.validate()?;
        ensure!(
            self.program == PROGRAM && self.current_dir == CURRENT_DIR,
            "stock worker program/current directory drifted"
        );
        ensure!(
            !self.args.is_empty()
                && self.args.iter().all(|value| !value.contains('\0'))
                && self.environment.iter().all(|(key, value)| !key.is_empty()
                    && !key.contains('=')
                    && !value.contains('\0')),
            "stock worker argv/environment is invalid"
        );
        let mut records = BTreeSet::new();
        for closure in &self.record_closures {
            closure.validate()?;
            ensure!(
                records.insert(normalize_distribution_name(&closure.distribution)),
                "duplicate RECORD closure for {:?}",
                closure.distribution
            );
        }
        for file in &self.embedded_files {
            file.validate()?;
        }
        for overlay in &self.metadata_overlays {
            overlay.validate(&self.record_closures)?;
        }
        Ok(())
    }
}

