#[derive(Debug, Deserialize)]
#[serde(deny_unknown_fields)]
struct RecordClosure {
    distribution: String,
    version: String,
    record_sha256: String,
    destination_prefix: String,
    omitted_paths: Vec<String>,
}

impl RecordClosure {
    fn validate(&self) -> Result<()> {
        ensure!(
            !self.distribution.trim().is_empty()
                && self.distribution.trim() == self.distribution
                && !self.version.trim().is_empty()
                && self.version.trim() == self.version,
            "RECORD distribution identity is invalid"
        );
        validate_sha256(&self.record_sha256, "RECORD SHA-256")?;
        strict_relative_path(&self.destination_prefix, "RECORD destination prefix")?;
        let mut omitted = BTreeSet::new();
        for path in &self.omitted_paths {
            strict_relative_path(path, "RECORD omitted path")?;
            ensure!(
                omitted.insert(path),
                "duplicate RECORD omitted path {path:?}"
            );
        }
        Ok(())
    }
}

#[derive(Debug, Deserialize)]
#[serde(deny_unknown_fields)]
struct EmbeddedFile {
    resource: String,
    destination: String,
    artifact_content_sha256: String,
    executable: bool,
    content_base64: String,
}

impl EmbeddedFile {
    fn validate(&self) -> Result<()> {
        ensure!(
            !self.resource.trim().is_empty(),
            "embedded resource is empty"
        );
        strict_relative_path(&self.destination, "embedded destination")?;
        validate_sha256(&self.artifact_content_sha256, "embedded file SHA-256")?;
        let content = decode_embedded(self)?;
        ensure!(
            accuracy::artifact_content_sha256(&content) == self.artifact_content_sha256,
            "embedded file digest mismatch for {:?}",
            self.destination
        );
        Ok(())
    }
}

#[derive(Debug, Deserialize)]
#[serde(deny_unknown_fields)]
struct MetadataOverlay {
    policy_id: String,
    distribution: String,
    version: String,
    upstream_record_sha256: String,
    omitted_paths: Vec<String>,
    replacement_files: Vec<EmbeddedFile>,
}

impl MetadataOverlay {
    fn validate(&self, closures: &[RecordClosure]) -> Result<()> {
        ensure!(
            matches!(
                self.policy_id.as_str(),
                "aiperf_source_attestation_v1" | "inspect_entry_point_policy_deny_v1"
            ),
            "unknown evaluator metadata overlay policy {:?}",
            self.policy_id
        );
        validate_sha256(&self.upstream_record_sha256, "overlay upstream RECORD")?;
        let closure = closures
            .iter()
            .find(|closure| {
                normalize_distribution_name(&closure.distribution)
                    == normalize_distribution_name(&self.distribution)
                    && closure.version == self.version
            })
            .ok_or_else(|| anyhow!("metadata overlay has no matching RECORD closure"))?;
        ensure!(
            closure.record_sha256 == self.upstream_record_sha256
                && closure.omitted_paths == self.omitted_paths,
            "metadata overlay RECORD/omission policy drifted"
        );
        let dist_info = dist_info_prefix(&self.distribution, &self.version);
        let required_omissions = ["METADATA", "RECORD", "direct_url.json"]
            .into_iter()
            .map(|name| format!("{dist_info}/{name}"))
            .collect::<BTreeSet<_>>();
        let actual_omissions = self.omitted_paths.iter().cloned().collect::<BTreeSet<_>>();
        ensure!(
            required_omissions.is_subset(&actual_omissions),
            "metadata overlay omitted-path set is incomplete"
        );
        let entry_points = format!("{dist_info}/entry_points.txt");
        ensure!(
            (self.policy_id == "inspect_entry_point_policy_deny_v1")
                == actual_omissions.contains(&entry_points),
            "Inspect entry-point denial policy drifted"
        );
        let required_replacements = ["METADATA", "RECORD", "aiperf_source_attestation.json"]
            .into_iter()
            .map(|name| format!("runtime/lib/python3.12/site-packages/{dist_info}/{name}"))
            .collect::<BTreeSet<_>>();
        let actual_replacements = self
            .replacement_files
            .iter()
            .map(|file| file.destination.clone())
            .collect::<BTreeSet<_>>();
        ensure!(
            actual_replacements == required_replacements
                && self.replacement_files.len() == required_replacements.len(),
            "metadata overlay replacement image drifted"
        );
        for file in &self.replacement_files {
            ensure!(
                !file.executable && file.resource.starts_with("generated://metadata-overlay/"),
                "metadata overlay replacement was not generated non-executable content"
            );
            file.validate()?;
        }
        Ok(())
    }
}

fn dist_info_prefix(distribution: &str, version: &str) -> String {
    format!("{}-{version}.dist-info", distribution.replace('-', "_"))
}

#[derive(Clone)]
enum MaterializationSource {
    Path(PathBuf),
    Bytes(Arc<[u8]>),
}

#[derive(Clone)]
struct ResolvedFile {
    source: MaterializationSource,
    digest: String,
    executable: bool,
}

struct ResolvedLaunchClosure {
    files: BTreeMap<String, ResolvedFile>,
}

impl ResolvedLaunchClosure {
    fn resolve(
        manifest: &StockDistributionManifest,
        distribution: &StockDistribution,
        resolver: &dyn StockClosureSourceResolver,
    ) -> Result<Self> {
        let mut files = BTreeMap::new();
        for closure_id in &distribution.launch.shared_closure_ids {
            let closure = manifest
                .shared_closures
                .get(closure_id)
                .ok_or_else(|| anyhow!("missing shared closure {closure_id:?}"))?;
            let source_root = match &closure.resolver {
                SharedClosureResolver::PythonRuntimeRoot(runtime) => {
                    resolver.python_runtime_root(runtime)?
                }
                SharedClosureResolver::SystemRoot(system) => resolver.system_root(system)?,
            };
            for file in &closure.files {
                let source = source_root.join(strict_relative_path(
                    &file.source_relative_path,
                    "shared source path",
                )?);
                let source = verified_source_path(&source, &file.artifact_content_sha256)?;
                insert_resolved(
                    &mut files,
                    &file.destination,
                    ResolvedFile {
                        source: MaterializationSource::Path(source),
                        digest: file.artifact_content_sha256.clone(),
                        executable: file.executable,
                    },
                )?;
            }
        }
        let site_roots = resolver.site_package_roots()?;
        for closure in &distribution.launch.record_closures {
            resolve_record_closure(closure, &site_roots, &mut files)?;
        }
        for file in &distribution.launch.embedded_files {
            let content: Arc<[u8]> = decode_embedded(file)?.into();
            insert_resolved(
                &mut files,
                &file.destination,
                ResolvedFile {
                    source: MaterializationSource::Bytes(content),
                    digest: file.artifact_content_sha256.clone(),
                    executable: file.executable,
                },
            )?;
        }
        for overlay in &distribution.launch.metadata_overlays {
            for file in &overlay.replacement_files {
                let content: Arc<[u8]> = decode_embedded(file)?.into();
                insert_resolved(
                    &mut files,
                    &file.destination,
                    ResolvedFile {
                        source: MaterializationSource::Bytes(content),
                        digest: file.artifact_content_sha256.clone(),
                        executable: file.executable,
                    },
                )?;
            }
        }
        let closure_digest = logical_closure_sha256(&files);
        ensure!(
            closure_digest == distribution.launch_closure_sha256,
            "resolved stock evaluator closure digest drifted"
        );
        ensure!(
            files.contains_key(PROGRAM),
            "worker program is absent from closure"
        );
        Ok(Self { files })
    }

    fn materialize(
        &self,
        root: &Path,
        distribution: &StockDistribution,
    ) -> Result<accuracy::AttestedWorkerLaunch> {
        for (destination, resolved) in &self.files {
            let destination_path = strict_relative_path(destination, "materialized destination")?;
            let target = root.join(&destination_path);
            let parent = target
                .parent()
                .ok_or_else(|| anyhow!("materialized destination has no parent"))?;
            create_secure_directories(root, parent)?;
            let content = match &resolved.source {
                MaterializationSource::Path(path) => read_verified_source(path, &resolved.digest)?,
                MaterializationSource::Bytes(content) => content.to_vec(),
            };
            ensure!(
                accuracy::artifact_content_sha256(&content) == resolved.digest,
                "materialized source digest drifted for {destination:?}"
            );
            let mut output = OpenOptions::new()
                .write(true)
                .create_new(true)
                .open(&target)
                .with_context(|| format!("creating worker-root file {}", target.display()))?;
            output
                .write_all(&content)
                .with_context(|| format!("writing worker-root file {}", target.display()))?;
            output
                .sync_all()
                .with_context(|| format!("syncing worker-root file {}", target.display()))?;
            set_file_mode(&target, if resolved.executable { 0o555 } else { 0o444 })?;
        }
        for relative in ROOTFS_MOUNTPOINTS {
            let directory = root.join(strict_relative_path(relative, "rootfs mountpoint")?);
            create_secure_directories(root, &directory)?;
            ensure_directory_empty(&directory)?;
            set_file_mode(&directory, 0o555)?;
        }
        preflight_materialized_root(root, &self.files)?;
        let closure = self
            .files
            .iter()
            .map(|(relative, file)| accuracy::LaunchClosureFile {
                path: root.join(relative),
                artifact_content_sha256: file.digest.clone(),
            })
            .collect();
        let launch = accuracy::AttestedWorkerLaunch {
            distribution_id: accuracy::EvaluationDistributionId::new(&distribution.distribution_id)
                .map_err(|error| anyhow!(error.to_string()))?,
            program: root.join(PROGRAM),
            args: distribution
                .launch
                .args
                .iter()
                .map(OsString::from)
                .collect(),
            environment: distribution
                .launch
                .environment
                .iter()
                .map(|(key, value)| (OsString::from(key), OsString::from(value)))
                .collect(),
            current_dir: root.join(CURRENT_DIR),
            worker_root: root.to_path_buf(),
            closure,
        };
        launch
            .validate()
            .map_err(|error| anyhow!(error.to_string()))?;
        Ok(launch)
    }
}

fn resolve_record_closure(
    closure: &RecordClosure,
    site_roots: &[PathBuf],
    files: &mut BTreeMap<String, ResolvedFile>,
) -> Result<()> {
    let (site_root, record_path, record_bytes) = locate_record_closure(closure, site_roots)
        .with_context(|| {
            format!(
                "resolving RECORD closure {} {}",
                closure.distribution, closure.version
            )
        })?;
    let omitted = closure.omitted_paths.iter().collect::<BTreeSet<_>>();
    let rows = parse_record_rows(&record_bytes)?;
    let mut row_paths = BTreeSet::new();
    for (relative, encoded_digest, encoded_size) in rows {
        ensure!(
            row_paths.insert(relative.clone()),
            "duplicate RECORD row {relative:?}"
        );
        if omitted.contains(&relative) {
            continue;
        }
        validate_record_relative(&relative)?;
        let source = site_root.join(Path::new(&relative));
        let expected = if encoded_digest.is_empty() {
            ensure!(
                source.canonicalize().ok().as_deref() == record_path.canonicalize().ok().as_deref(),
                "only the RECORD file may omit its own digest"
            );
            closure.record_sha256.clone()
        } else {
            decode_record_digest(&encoded_digest)?
        };
        let source = verified_source_path(&source, &expected)?;
        let environment_root = site_root
            .ancestors()
            .nth(3)
            .ok_or_else(|| anyhow!("site-packages root has no environment ancestor"))?
            .canonicalize()
            .context("canonicalizing Python environment root")?;
        ensure!(
            source.starts_with(&environment_root),
            "RECORD source escaped its Python environment root"
        );
        let metadata = source
            .metadata()
            .with_context(|| format!("inspecting RECORD source {}", source.display()))?;
        if !encoded_size.is_empty() {
            let expected_size: u64 = encoded_size
                .parse()
                .with_context(|| format!("invalid RECORD size for {relative:?}"))?;
            ensure!(
                metadata.len() == expected_size,
                "RECORD size drift for {relative:?}"
            );
        }
        let destination = logical_join(&closure.destination_prefix, &relative)?;
        insert_resolved(
            files,
            &destination,
            ResolvedFile {
                source: MaterializationSource::Path(source.clone()),
                digest: expected,
                executable: is_executable(&source)?,
            },
        )?;
    }
    ensure!(
        omitted.iter().all(|path| row_paths.contains(*path)),
        "RECORD omitted-path policy named a missing row"
    );
    Ok(())
}

fn locate_record_closure(
    closure: &RecordClosure,
    site_roots: &[PathBuf],
) -> Result<(PathBuf, PathBuf, Vec<u8>)> {
    let expected_name = normalize_distribution_name(&closure.distribution);
    let mut matches = Vec::new();
    for site_root in site_roots {
        for entry in std::fs::read_dir(site_root)
            .with_context(|| format!("enumerating site-packages {}", site_root.display()))?
        {
            let entry = entry.context("reading site-packages entry")?;
            let path = entry.path();
            if !entry.file_name().to_string_lossy().ends_with(".dist-info") {
                continue;
            }
            let metadata = std::fs::symlink_metadata(&path)
                .with_context(|| format!("inspecting dist-info {}", path.display()))?;
            if !metadata.file_type().is_dir() || metadata.file_type().is_symlink() {
                continue;
            }
            let metadata_bytes = match std::fs::read(path.join("METADATA")) {
                Ok(bytes) => bytes,
                Err(_) => continue,
            };
            let (name, version) = metadata_identity(&metadata_bytes)?;
            if normalize_distribution_name(&name) != expected_name || version != closure.version {
                continue;
            }
            let record_path = path.join("RECORD");
            let record_bytes = std::fs::read(&record_path)
                .with_context(|| format!("reading RECORD {}", record_path.display()))?;
            ensure!(
                accuracy::artifact_content_sha256(&record_bytes) == closure.record_sha256,
                "installed RECORD digest drift for {}",
                closure.distribution
            );
            matches.push((site_root.clone(), record_path, record_bytes));
        }
    }
    ensure!(
        matches.len() == 1,
        "distribution {} {} resolved to {} installed RECORDs",
        closure.distribution,
        closure.version,
        matches.len()
    );
    Ok(matches.remove(0))
}

fn metadata_identity(bytes: &[u8]) -> Result<(String, String)> {
    let text = std::str::from_utf8(bytes).context("dist-info METADATA was not UTF-8")?;
    let mut name = None;
    let mut version = None;
    for line in text.lines().take_while(|line| !line.is_empty()) {
        if let Some(value) = line.strip_prefix("Name: ") {
            ensure!(
                name.replace(value.to_string()).is_none(),
                "duplicate METADATA Name"
            );
        }
        if let Some(value) = line.strip_prefix("Version: ") {
            ensure!(
                version.replace(value.to_string()).is_none(),
                "duplicate METADATA Version"
            );
        }
    }
    Ok((
        name.ok_or_else(|| anyhow!("METADATA omitted Name"))?,
        version.ok_or_else(|| anyhow!("METADATA omitted Version"))?,
    ))
}

fn parse_record_rows(bytes: &[u8]) -> Result<Vec<(String, String, String)>> {
    let mut reader = csv::ReaderBuilder::new()
        .has_headers(false)
        .flexible(false)
        .from_reader(bytes);
    let mut rows = Vec::new();
    for row in reader.records() {
        let row = row.context("decoding distribution RECORD CSV")?;
        ensure!(
            row.len() == 3,
            "distribution RECORD row must have three fields"
        );
        let relative = row.get(0).expect("length checked").to_string();
        validate_record_relative(&relative)?;
        rows.push((
            relative,
            row.get(1).expect("length checked").to_string(),
            row.get(2).expect("length checked").to_string(),
        ));
    }
    ensure!(!rows.is_empty(), "distribution RECORD is empty");
    Ok(rows)
}

fn decode_record_digest(encoded: &str) -> Result<String> {
    let payload = encoded
        .strip_prefix("sha256=")
        .ok_or_else(|| anyhow!("RECORD digest does not use sha256"))?;
    let bytes = URL_SAFE_NO_PAD
        .decode(payload)
        .context("decoding RECORD SHA-256")?;
    ensure!(bytes.len() == 32, "RECORD SHA-256 has the wrong length");
    Ok(bytes.iter().map(|byte| format!("{byte:02x}")).collect())
}

fn decode_embedded(file: &EmbeddedFile) -> Result<Vec<u8>> {
    BASE64_STANDARD
        .decode(&file.content_base64)
        .with_context(|| format!("decoding embedded resource {:?}", file.resource))
}

fn insert_resolved(
    files: &mut BTreeMap<String, ResolvedFile>,
    destination: &str,
    resolved: ResolvedFile,
) -> Result<()> {
    let destination = path_to_logical(&strict_relative_path(
        destination,
        "launch closure destination",
    )?)?;
    ensure!(
        files.insert(destination.clone(), resolved).is_none(),
        "duplicate launch closure destination {destination:?}"
    );
    Ok(())
}

fn logical_closure_sha256(files: &BTreeMap<String, ResolvedFile>) -> String {
    let mut bytes = Vec::new();
    for (path, file) in files {
        bytes.extend_from_slice(path.as_bytes());
        bytes.push(0);
        bytes.extend_from_slice(file.digest.as_bytes());
        bytes.push(b'\n');
    }
    accuracy::artifact_content_sha256(&bytes)
}

fn preflight_materialized_root(
    root: &Path,
    expected: &BTreeMap<String, ResolvedFile>,
) -> Result<()> {
    let root = root
        .canonicalize()
        .with_context(|| format!("canonicalizing worker root {}", root.display()))?;
    let mut actual = BTreeMap::new();
    let mut pending = vec![root.clone()];
    while let Some(directory) = pending.pop() {
        for entry in std::fs::read_dir(&directory)
            .with_context(|| format!("enumerating worker root {}", directory.display()))?
        {
            let entry = entry.context("reading worker-root entry")?;
            let path = entry.path();
            let metadata = std::fs::symlink_metadata(&path)
                .with_context(|| format!("inspecting worker-root entry {}", path.display()))?;
            if metadata.file_type().is_dir() && !metadata.file_type().is_symlink() {
                pending.push(path);
                continue;
            }
            ensure!(
                metadata.file_type().is_file() && !metadata.file_type().is_symlink(),
                "worker root contains a symlink or special file"
            );
            #[cfg(unix)]
            {
                use std::os::unix::fs::MetadataExt as _;
                ensure!(metadata.nlink() == 1, "worker-root file is a hard link");
            }
            let relative = path
                .strip_prefix(&root)
                .context("worker-root entry escaped root")?;
            let relative = path_to_logical(relative)?;
            actual.insert(
                relative,
                ResolvedFile {
                    source: MaterializationSource::Path(path.clone()),
                    digest: accuracy::artifact_content_sha256(&std::fs::read(&path)?),
                    executable: is_executable(&path)?,
                },
            );
        }
    }
    ensure!(
        actual.len() == expected.len()
            && actual.iter().all(|(path, file)| {
                expected.get(path).is_some_and(|expected| {
                    expected.digest == file.digest && expected.executable == file.executable
                })
            }),
        "materialized rootfs file inventory drifted"
    );
    ensure!(
        logical_closure_sha256(&actual) == logical_closure_sha256(expected),
        "materialized rootfs closure digest drifted"
    );
    for relative in ROOTFS_MOUNTPOINTS {
        ensure_directory_empty(&root.join(relative))?;
    }
    Ok(())
}

fn create_secure_directories(root: &Path, destination: &Path) -> Result<()> {
    let relative = destination
        .strip_prefix(root)
        .context("worker-root directory escaped root")?;
    let mut current = root.to_path_buf();
    for component in relative.components() {
        let Component::Normal(component) = component else {
            bail!("worker-root directory contained a non-normal component");
        };
        current.push(component);
        match std::fs::symlink_metadata(&current) {
            Ok(metadata) => ensure!(
                metadata.file_type().is_dir() && !metadata.file_type().is_symlink(),
                "worker-root parent is not a real directory"
            ),
            Err(error) if error.kind() == std::io::ErrorKind::NotFound => {
                std::fs::create_dir(&current).with_context(|| {
                    format!("creating worker-root directory {}", current.display())
                })?;
                set_file_mode(&current, 0o755)?;
            }
            Err(error) => return Err(error.into()),
        }
    }
    Ok(())
}

fn ensure_directory_empty(path: &Path) -> Result<()> {
    let metadata = std::fs::symlink_metadata(path)
        .with_context(|| format!("inspecting rootfs mountpoint {}", path.display()))?;
    ensure!(
        metadata.file_type().is_dir() && !metadata.file_type().is_symlink(),
        "rootfs mountpoint is not a real directory"
    );
    ensure!(
        std::fs::read_dir(path)
            .with_context(|| format!("enumerating rootfs mountpoint {}", path.display()))?
            .next()
            .is_none(),
        "rootfs mountpoint {} is not empty",
        path.display()
    );
    Ok(())
}

fn verified_source_path(path: &Path, expected_digest: &str) -> Result<PathBuf> {
    let canonical = path
        .canonicalize()
        .with_context(|| format!("canonicalizing closure source {}", path.display()))?;
    verify_regular_file_digest(&canonical, expected_digest)?;
    Ok(canonical)
}

fn verify_regular_file_digest(path: &Path, expected_digest: &str) -> Result<()> {
    let metadata = std::fs::symlink_metadata(path)
        .with_context(|| format!("inspecting closure source {}", path.display()))?;
    ensure!(
        metadata.file_type().is_file() && !metadata.file_type().is_symlink(),
        "closure source {} is not a regular non-symlink file",
        path.display()
    );
    let content = read_file(path)?;
    ensure!(
        accuracy::artifact_content_sha256(&content) == expected_digest,
        "closure source digest drift for {}",
        path.display()
    );
    Ok(())
}

fn read_verified_source(path: &Path, expected_digest: &str) -> Result<Vec<u8>> {
    verify_regular_file_digest(path, expected_digest)?;
    read_file(path)
}

fn read_file(path: &Path) -> Result<Vec<u8>> {
    let mut input =
        File::open(path).with_context(|| format!("opening closure source {}", path.display()))?;
    let metadata = input
        .metadata()
        .with_context(|| format!("inspecting opened closure source {}", path.display()))?;
    ensure!(metadata.is_file(), "opened closure source is not a file");
    let mut content = Vec::new();
    input
        .read_to_end(&mut content)
        .with_context(|| format!("reading closure source {}", path.display()))?;
    Ok(content)
}

fn is_executable(path: &Path) -> Result<bool> {
    #[cfg(unix)]
    {
        use std::os::unix::fs::PermissionsExt as _;
        Ok(path
            .metadata()
            .with_context(|| format!("inspecting executable bit {}", path.display()))?
            .permissions()
            .mode()
            & 0o111
            != 0)
    }
    #[cfg(not(unix))]
    {
        let _ = path;
        Ok(false)
    }
}

fn set_file_mode(path: &Path, mode: u32) -> Result<()> {
    #[cfg(unix)]
    {
        use std::os::unix::fs::PermissionsExt as _;
        std::fs::set_permissions(path, std::fs::Permissions::from_mode(mode))
            .with_context(|| format!("setting worker-root mode for {}", path.display()))?;
    }
    #[cfg(not(unix))]
    {
        let _ = (path, mode);
    }
    Ok(())
}

fn strict_relative_path(value: &str, field: &str) -> Result<PathBuf> {
    ensure!(
        !value.is_empty() && !value.contains('\\') && !value.contains('\0'),
        "{field} is not a canonical logical path"
    );
    let path = Path::new(value);
    ensure!(!path.is_absolute(), "{field} must be relative");
    ensure!(
        path.components()
            .all(|component| matches!(component, Component::Normal(_))),
        "{field} must contain only normal components"
    );
    Ok(path.to_path_buf())
}

fn validate_record_relative(value: &str) -> Result<()> {
    ensure!(
        !value.is_empty()
            && !value.starts_with('/')
            && !value.contains('\\')
            && !value.contains('\0'),
        "RECORD path is not relative"
    );
    ensure!(
        value
            .split('/')
            .any(|part| !matches!(part, "" | "." | "..")),
        "RECORD path normalized empty"
    );
    Ok(())
}

fn logical_join(prefix: &str, relative: &str) -> Result<String> {
    let mut parts = prefix
        .split('/')
        .filter(|part| !part.is_empty() && *part != ".")
        .map(str::to_owned)
        .collect::<Vec<_>>();
    for part in relative.split('/') {
        match part {
            "" | "." => {}
            ".." => {
                ensure!(parts.pop().is_some(), "logical destination escaped root");
            }
            value => parts.push(value.to_owned()),
        }
    }
    ensure!(!parts.is_empty(), "logical destination normalized empty");
    let output = parts.join("/");
    strict_relative_path(&output, "logical destination")?;
    Ok(output)
}

fn path_to_logical(path: &Path) -> Result<String> {
    path.to_str()
        .map(str::to_owned)
        .ok_or_else(|| anyhow!("logical path was not UTF-8"))
}

fn validate_python_identity(
    implementation: &str,
    version: &str,
    abi: &str,
    platform: &str,
) -> Result<()> {
    ensure!(
        implementation == PYTHON_IMPLEMENTATION
            && version == PYTHON_VERSION
            && abi == PYTHON_ABI
            && platform == PLATFORM,
        "stock evaluator Python identity drifted"
    );
    Ok(())
}

fn validate_sha256(value: &str, field: &str) -> Result<()> {
    ensure!(
        accuracy::is_sha256(value),
        "{field} is not a lowercase SHA-256"
    );
    Ok(())
}

fn validate_open_manifest_id(value: &str, field: &str) -> Result<()> {
    ensure!(
        !value.is_empty()
            && value.bytes().all(|byte| {
                byte.is_ascii_lowercase()
                    || byte.is_ascii_digit()
                    || matches!(byte, b'_' | b'-' | b'.')
            }),
        "{field} is invalid"
    );
    Ok(())
}

fn normalize_distribution_name(value: &str) -> String {
    let mut output = String::new();
    let mut separator = false;
    for character in value.chars() {
        if matches!(character, '-' | '_' | '.') {
            separator = !output.is_empty();
        } else {
            if separator {
                output.push('-');
                separator = false;
            }
            output.extend(character.to_lowercase());
        }
    }
    output
}

struct MaterializedRootGuard {
    root: Option<PathBuf>,
}

impl fmt::Debug for MaterializedRootGuard {
    fn fmt(&self, formatter: &mut fmt::Formatter<'_>) -> fmt::Result {
        formatter
            .debug_struct("MaterializedRootGuard")
            .field("active", &self.root.is_some())
            .finish()
    }
}

impl MaterializedRootGuard {
    fn create(parent: &Path) -> Result<Self> {
        let parent = parent
            .canonicalize()
            .with_context(|| format!("canonicalizing worker-root parent {}", parent.display()))?;
        for _ in 0..8 {
            let root = parent.join(format!("worker-root-{}", Uuid::new_v4().simple()));
            match std::fs::create_dir(&root) {
                Ok(()) => {
                    set_file_mode(&root, 0o700)?;
                    return Ok(Self { root: Some(root) });
                }
                Err(error) if error.kind() == std::io::ErrorKind::AlreadyExists => continue,
                Err(error) => return Err(error.into()),
            }
        }
        bail!("failed to allocate an exclusive evaluator worker root")
    }

    fn path(&self) -> &Path {
        self.root.as_deref().expect("active materialized root")
    }

    fn after_worker_shutdown(&self) {
        // Quiescence is proven by the delegated provider. The immutable root
        // intentionally remains until report commit binds its provenance.
    }

    fn after_artifacts_sealed(&self) {
        // Artifact sealing also precedes report commit; keep the root alive.
    }

    fn after_report_commit(&mut self) -> Result<()> {
        self.cleanup()
    }

    fn cleanup(&mut self) -> Result<()> {
        let Some(root) = self.root.as_ref() else {
            return Ok(());
        };
        ensure!(
            root.file_name()
                .and_then(|name| name.to_str())
                .is_some_and(|name| name.starts_with("worker-root-")),
            "refusing to clean an unrecognized evaluator root"
        );
        std::fs::remove_dir_all(root)
            .with_context(|| format!("removing materialized evaluator root {}", root.display()))?;
        ensure!(
            !root.exists(),
            "materialized evaluator root remained after cleanup"
        );
        self.root = None;
        Ok(())
    }
}

impl Drop for MaterializedRootGuard {
    fn drop(&mut self) {
        if let Err(error) = self.cleanup() {
            tracing::error!(error = %error, "failed to clean materialized evaluator root on drop");
        }
    }
}

struct StockPreparedLaunch {
    distribution_id: accuracy::EvaluationDistributionId,
    prelaunch_context_sha256: String,
    isolation_evidence: accuracy::EvaluatorIsolationEvidence,
    inner_launcher: Arc<accuracy::SupervisedEvaluationProviderLauncher>,
    inner: Box<dyn accuracy::PreparedEvaluationProviderLaunch>,
    root: MaterializedRootGuard,
    authority: Arc<()>,
}

impl fmt::Debug for StockPreparedLaunch {
    fn fmt(&self, formatter: &mut fmt::Formatter<'_>) -> fmt::Result {
        formatter
            .debug_struct("StockPreparedLaunch")
            .field("distribution_id", &self.distribution_id)
            .field("root", &self.root)
            .finish_non_exhaustive()
    }
}

impl accuracy::PreparedEvaluationProviderLaunch for StockPreparedLaunch {
    fn distribution_id(&self) -> &accuracy::EvaluationDistributionId {
        &self.distribution_id
    }

    fn prelaunch_context_sha256(&self) -> &str {
        &self.prelaunch_context_sha256
    }

    fn isolation_evidence(&self) -> &accuracy::EvaluatorIsolationEvidence {
        &self.isolation_evidence
    }

    fn into_any(self: Box<Self>) -> Box<dyn Any + Send> {
        self
    }
}

struct StockEvaluationProviderLauncher {
    manifest: Arc<StockDistributionManifest>,
    distribution_id: accuracy::EvaluationDistributionId,
    sources: Arc<dyn StockClosureSourceResolver>,
    authority: Arc<()>,
}

impl fmt::Debug for StockEvaluationProviderLauncher {
    fn fmt(&self, formatter: &mut fmt::Formatter<'_>) -> fmt::Result {
        formatter
            .debug_struct("StockEvaluationProviderLauncher")
            .field("distribution_id", &self.distribution_id)
            .finish_non_exhaustive()
    }
}

impl StockEvaluationProviderLauncher {
    fn new(
        manifest: Arc<StockDistributionManifest>,
        distribution_id: accuracy::EvaluationDistributionId,
    ) -> Self {
        Self {
            manifest,
            distribution_id,
            sources: Arc::new(EnvironmentStockClosureSourceResolver),
            authority: Arc::new(()),
        }
    }

    fn entry(&self) -> Result<&StockDistribution> {
        self.manifest.distribution(&self.distribution_id)
    }

    fn validate_descriptor(
        &self,
        descriptor: &accuracy::EvaluationProviderDescriptor,
        distribution: &accuracy::EvaluationDistributionDescriptor,
    ) -> Result<()> {
        let entry = self.entry()?;
        ensure!(
            descriptor.provider_id.as_str() == entry.provider_id
                && descriptor.config_schema_version == entry.config_schema_version
                && descriptor.config_schema_sha256 == entry.config_schema_sha256
                && distribution == &entry.descriptor()?,
            "stock provider descriptor drifted from embedded manifest"
        );
        Ok(())
    }
}

#[async_trait(?Send)]
impl accuracy::EvaluationProviderLauncher for StockEvaluationProviderLauncher {
    fn check_distribution_available(
        &self,
        distribution: &accuracy::EvaluationDistributionDescriptor,
    ) -> std::result::Result<(), accuracy::EvaluationProviderError> {
        let entry = self
            .entry()
            .map_err(|error| accuracy::EvaluationProviderError::Launch(format!("{error:#}")))?;
        if distribution
            != &entry
                .descriptor()
                .map_err(|error| accuracy::EvaluationProviderError::Launch(format!("{error:#}")))?
        {
            return Err(accuracy::EvaluationProviderError::FactoryMismatch(
                "stock distribution descriptor drifted from embedded manifest".to_owned(),
            ));
        }
        ResolvedLaunchClosure::resolve(self.manifest.as_ref(), entry, self.sources.as_ref())
            .map_err(|error| accuracy::EvaluationProviderError::Launch(format!("{error:#}")))?;
        entry
            .isolation
            .implementation()
            .and_then(|isolation| {
                isolation
                    .check_available()
                    .map_err(|error| anyhow!(error.to_string()))
            })
            .map_err(|error| accuracy::EvaluationProviderError::Launch(format!("{error:#}")))
    }

    fn prepare_launch(
        &self,
        descriptor: &accuracy::EvaluationProviderDescriptor,
        distribution: &accuracy::EvaluationDistributionDescriptor,
        context: accuracy::ProviderLaunchContext,
    ) -> std::result::Result<
        Box<dyn accuracy::PreparedEvaluationProviderLaunch>,
        accuracy::EvaluationProviderError,
    > {
        self.validate_descriptor(descriptor, distribution)
            .map_err(|error| {
                accuracy::EvaluationProviderError::FactoryMismatch(format!("{error:#}"))
            })?;
        let entry = self
            .entry()
            .map_err(|error| accuracy::EvaluationProviderError::Launch(format!("{error:#}")))?;
        let closure =
            ResolvedLaunchClosure::resolve(self.manifest.as_ref(), entry, self.sources.as_ref())
                .map_err(|error| accuracy::EvaluationProviderError::Launch(format!("{error:#}")))?;
        let parent = context.staging_dir.parent().ok_or_else(|| {
            accuracy::EvaluationProviderError::Launch(
                "evaluation staging root has no parent for worker root".to_owned(),
            )
        })?;
        let root = MaterializedRootGuard::create(parent)
            .map_err(|error| accuracy::EvaluationProviderError::Launch(format!("{error:#}")))?;
        let launch = closure
            .materialize(root.path(), entry)
            .map_err(|error| accuracy::EvaluationProviderError::Launch(format!("{error:#}")))?;
        let inner_launcher = Arc::new(accuracy::SupervisedEvaluationProviderLauncher::new(
            vec![launch],
            Arc::new(accuracy::Sha256LaunchAttestor),
            entry
                .isolation
                .implementation()
                .map_err(|error| accuracy::EvaluationProviderError::Launch(format!("{error:#}")))?,
        )?);
        let inner = inner_launcher.prepare_launch(descriptor, distribution, context)?;
        Ok(Box::new(StockPreparedLaunch {
            distribution_id: inner.distribution_id().clone(),
            prelaunch_context_sha256: inner.prelaunch_context_sha256().to_owned(),
            isolation_evidence: inner.isolation_evidence().clone(),
            inner_launcher,
            inner,
            root,
            authority: self.authority.clone(),
        }))
    }

    async fn launch(
        &self,
        descriptor: &accuracy::EvaluationProviderDescriptor,
        config: &accuracy::ValidatedProviderConfig,
        host_binding: accuracy::EvaluationHostBinding,
        prepared: Box<dyn accuracy::PreparedEvaluationProviderLaunch>,
    ) -> std::result::Result<Box<dyn accuracy::EvaluationProvider>, accuracy::EvaluationProviderError>
    {
        let prepared = prepared
            .into_any()
            .downcast::<StockPreparedLaunch>()
            .map_err(|_| {
                accuracy::EvaluationProviderError::FactoryMismatch(
                    "stock launcher received a foreign prepared token".to_owned(),
                )
            })?;
        if !Arc::ptr_eq(&prepared.authority, &self.authority)
            || prepared.distribution_id != self.distribution_id
        {
            return Err(accuracy::EvaluationProviderError::FactoryMismatch(
                "stock prepared-launch authority drifted".to_owned(),
            ));
        }
        let StockPreparedLaunch {
            inner_launcher,
            inner,
            root,
            ..
        } = *prepared;
        let inner = inner_launcher
            .launch(descriptor, config, host_binding, inner)
            .await?;
        Ok(Box::new(MaterializedEvaluationProvider { inner, root }))
    }
}

struct MaterializedEvaluationProvider {
    inner: Box<dyn accuracy::EvaluationProvider>,
    root: MaterializedRootGuard,
}

#[async_trait(?Send)]
impl accuracy::EvaluationProvider for MaterializedEvaluationProvider {
    fn identity(&self) -> &accuracy::EvaluationWorkerIdentity {
        self.inner.identity()
    }

    fn lifecycle_state(&self) -> accuracy::EvaluationLifecycleState {
        self.inner.lifecycle_state()
    }

    fn quiescence_proof(&self) -> Option<&accuracy::IsolationQuiescenceProof> {
        self.inner.quiescence_proof()
    }

    async fn plan(
        &mut self,
        request: &accuracy::EvaluationPlanRequest,
    ) -> std::result::Result<accuracy::EvaluationPlan, accuracy::EvaluationProviderError> {
        self.inner.plan(request).await
    }

    async fn bind_assets(
        &mut self,
        assets: &[accuracy::ResolvedEvaluationAsset],
    ) -> std::result::Result<accuracy::EvaluationIdentity, accuracy::EvaluationProviderError> {
        self.inner.bind_assets(assets).await
    }

    async fn next_units(
        &mut self,
        offset: usize,
        limit: usize,
    ) -> std::result::Result<accuracy::EvaluationUnitPage, accuracy::EvaluationProviderError> {
        self.inner.next_units(offset, limit).await
    }

    async fn instantiate_units(
        &mut self,
        requests: &[accuracy::EvaluationUnitOccurrenceRequest],
    ) -> std::result::Result<
        Vec<accuracy::EvaluationUnitOccurrence>,
        accuracy::EvaluationProviderError,
    > {
        self.inner.instantiate_units(requests).await
    }

    async fn start_units(
        &mut self,
        ids: &[accuracy::EvaluationUnitId],
    ) -> std::result::Result<(), accuracy::EvaluationProviderError> {
        self.inner.start_units(ids).await
    }

    async fn poll_events(
        &mut self,
        limit: usize,
        wait_ms: u64,
    ) -> std::result::Result<accuracy::EvaluationEventBatch, accuracy::EvaluationProviderError>
    {
        self.inner.poll_events(limit, wait_ms).await
    }

    async fn submit_host_events(
        &mut self,
        events: &[accuracy::HostOperationEvent],
    ) -> std::result::Result<(), accuracy::EvaluationProviderError> {
        self.inner.submit_host_events(events).await
    }

    async fn cancel_units(
        &mut self,
        ids: &[accuracy::EvaluationUnitId],
    ) -> std::result::Result<(), accuracy::EvaluationProviderError> {
        self.inner.cancel_units(ids).await
    }

    async fn finalize_candidate(
        &mut self,
    ) -> std::result::Result<accuracy::EvaluationFinishCandidate, accuracy::EvaluationProviderError>
    {
        self.inner.finalize_candidate().await
    }

    async fn shutdown(&mut self) -> std::result::Result<(), accuracy::EvaluationProviderError> {
        self.inner.shutdown().await?;
        self.root.after_worker_shutdown();
        Ok(())
    }

    fn mark_artifacts_sealed(
        &mut self,
    ) -> std::result::Result<(), accuracy::EvaluationProviderError> {
        self.inner.mark_artifacts_sealed()?;
        self.root.after_artifacts_sealed();
        Ok(())
    }

    fn mark_report_committed(
        &mut self,
    ) -> std::result::Result<(), accuracy::EvaluationProviderError> {
        self.inner.mark_report_committed()?;
        self.root
            .after_report_commit()
            .map_err(|error| accuracy::EvaluationProviderError::Quiescence(format!("{error:#}")))
    }
}

/// Build the exact frozen stock provider registry from the embedded manifest.
pub(crate) fn stock_provider_registry() -> Result<Arc<accuracy::EvaluationProviderRegistry>> {
    let manifest = Arc::new(StockDistributionManifest::embedded()?);
    let mut builder = accuracy::EvaluationProviderRegistryBuilder::new();
    for entry in &manifest.distributions {
        let distribution = entry.descriptor()?;
        let launcher: Arc<dyn accuracy::EvaluationProviderLauncher> =
            Arc::new(StockEvaluationProviderLauncher::new(
                manifest.clone(),
                distribution.distribution_id.clone(),
            ));
        let factory: Arc<dyn accuracy::EvaluationProviderFactory> = match entry.provider_id.as_str()
        {
            "nemo_evaluator" => Arc::new(accuracy::NemoEvaluatorProviderFactory::new(
                vec![distribution],
                launcher,
            )?),
            "openbench" => Arc::new(accuracy::OpenBenchProviderFactory::new(
                vec![distribution],
                launcher,
            )?),
            provider => bail!("unregistered stock evaluator provider {provider:?}"),
        };
        ensure!(
            factory.descriptor().config_schema_version == entry.config_schema_version
                && factory.descriptor().config_schema_sha256 == entry.config_schema_sha256,
            "stock provider factory schema drifted from manifest for {:?}",
            entry.provider_id
        );
        builder.register(factory)?;
    }
    Ok(Arc::new(builder.freeze()?))
}

#[cfg(test)]
mod tests {
    use super::*;

    #[test]
    fn embedded_manifest_is_strict_and_identity_complete() {
        let manifest = StockDistributionManifest::embedded().unwrap();
        assert_eq!(manifest.distributions.len(), 2);
        assert_eq!(
            manifest
                .distributions
                .iter()
                .map(|entry| entry.provider_id.as_str())
                .collect::<Vec<_>>(),
            ["nemo_evaluator", "openbench"]
        );
        for entry in &manifest.distributions {
            assert_eq!(entry.isolation.profile_id, ISOLATION_PROFILE);
            assert!(entry.launch.shared_closure_ids.len() >= 2);
            assert_eq!(entry.launch.program, PROGRAM);
            assert_eq!(entry.launch.current_dir, CURRENT_DIR);
        }
    }

    #[test]
    fn manifest_rejects_unknown_fields() {
        let mut value: serde_json::Value = serde_json::from_slice(STOCK_MANIFEST_BYTES).unwrap();
        value["unexpected"] = serde_json::json!(true);
        let error = serde_json::from_value::<StockDistributionManifest>(value)
            .unwrap_err()
            .to_string();
        assert!(error.contains("unknown field"), "{error}");
    }

    #[test]
    fn installed_stock_source_closures_resolve_to_exact_manifest_digests() {
        let manifest = StockDistributionManifest::embedded().unwrap();
        let resolver = EnvironmentStockClosureSourceResolver;
        for distribution in &manifest.distributions {
            let closure =
                ResolvedLaunchClosure::resolve(&manifest, distribution, &resolver).unwrap();
            assert_eq!(
                logical_closure_sha256(&closure.files),
                distribution.launch_closure_sha256
            );
            assert!(closure.files.contains_key(PROGRAM));
            assert!(closure.files.contains_key("assets/gsm8k_canary.jsonl"));
        }
    }

    #[test]
    fn both_stock_rootfs_images_materialize_and_pass_independent_attestation() {
        let manifest = StockDistributionManifest::embedded().unwrap();
        let resolver = EnvironmentStockClosureSourceResolver;
        let temporary = tempfile::tempdir().unwrap();
        for distribution in &manifest.distributions {
            let closure =
                ResolvedLaunchClosure::resolve(&manifest, distribution, &resolver).unwrap();
            let root = temporary.path().join(&distribution.distribution_id);
            std::fs::create_dir(&root).unwrap();
            let launch = closure.materialize(&root, distribution).unwrap();
            let descriptor = distribution.descriptor().unwrap();
            let attestation = accuracy::EvaluatorLaunchAttestor::attest(
                &accuracy::Sha256LaunchAttestor,
                &launch,
                &descriptor,
            )
            .unwrap();
            assert_eq!(
                attestation.launch_closure_sha256,
                distribution.launch_closure_sha256
            );
            for mountpoint in ROOTFS_MOUNTPOINTS {
                ensure_directory_empty(&root.join(mountpoint)).unwrap();
            }
        }
    }

    #[test]
    fn materialized_root_lives_through_shutdown_and_sealing_until_report_commit() {
        let temporary = tempfile::tempdir().unwrap();
        let mut guard = MaterializedRootGuard::create(temporary.path()).unwrap();
        let root = guard.path().to_path_buf();
        assert!(root.is_dir());
        guard.after_worker_shutdown();
        assert!(root.is_dir());
        guard.after_artifacts_sealed();
        assert!(root.is_dir());
        guard.after_report_commit().unwrap();
        assert!(!root.exists());
    }

    #[test]
    fn materialized_root_is_removed_on_error_drop_path() {
        let temporary = tempfile::tempdir().unwrap();
        let root = {
            let guard = MaterializedRootGuard::create(temporary.path()).unwrap();
            let root = guard.path().to_path_buf();
            assert!(root.is_dir());
            root
        };
        assert!(!root.exists());
    }
}
